describe('Checkout Form - Card Expiry Validation', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should validate card expiry in MM/YY format and display error message for invalid format', () => {
    // Intercept the API call to validate card expiry
    cy.intercept('POST', '/api/validate-card-expiry', {
      statusCode: 200,
      body: {
        isValid: false,
        error: 'Invalid expiry format. Please use MM/YY format.'
      }
    }).as('validateExpiry');

    // Fill in the card expiry field with invalid format
    cy.get('[data-testid="card-expiry-input"]').type('12/3456');

    // Submit the form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for the API validation
    cy.wait('@validateExpiry');

    // Verify error message is displayed
    cy.get('[data-testid="expiry-error-message"]')
      .should('be.visible')
      .should('contain', 'Invalid expiry format');

    // Verify form is not submitted
    cy.get('[data-testid="order-summary"]').should('not.exist');
  });

  it('should validate card expiry in MM/YY format and allow submission with valid format', () => {
    // Intercept the API call to validate card expiry
    cy.intercept('POST', '/api/validate-card-expiry', {
      statusCode: 200,
      body: {
        isValid: true,
        error: null
      }
    }).as('validateExpiry');

    // Fill in the card expiry field with valid format
    cy.get('[data-testid="card-expiry-input"]').type('12/23');

    // Submit the form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for the API validation
    cy.wait('@validateExpiry');

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]')
      .should('be.visible')
      .should('contain', 'Card expiry validated successfully');

    // Verify order summary appears
    cy.get('[data-testid="order-summary"]').should('be.visible');
  });
});
